-- Fail fast on missing GameSettings keys, but only when the extension is active
local warned = {}
setmetatable(GameSettings, {
    __index = function(t, k)
        -- Only enforce strict nil-access guard when the extension has initialized
        local roguemon = rawget(_G, "Roguemon")
        if not roguemon or not roguemon.initialized then
            return nil
        end
        local msg = string.format("GameSettings.%s is nil", tostring(k))
        if warned[k] == nil then
            warned[k] = true
            Utils.printDebug("[WARN] %s", msg)
        end
        if not warned.__fatal then
            warned.__fatal = true
            local main = rawget(_G, "Main")
            if main and main.DisplayError then
                main.DisplayError(msg .. "\n\nRogueMon GameSettings is missing data. The tracker will now exit.")
            end
            if main and main.ExitSafely then
                main.ExitSafely(true)
            end
        end
        error(msg)
    end
})

-- Critical fields that must be present and non-zero for the tracker to function
local REQUIRED_POINTER_FIELDS = {
    -- Save block pointers (used for state reads/writes)
    "gSaveBlock1ptr",
    "gSaveBlock2ptr",
    "gSaveBlock3ptr",
    -- Main state detection
    "gMainAddr",
    "overworldAddr",
    -- Battle data addresses
    "gBattleMons",
    "gPlayerParty",
    "gEnemyParty",
    "gBattleTypeFlags",
    -- Data table addresses
    "gSpeciesInfo",
    "gBattleMoves",
    "gAbilitiesInfo",
    "gItemsInfo",
    -- RogueMon-specific addresses
    "roguemonTrackerDataAddr",
    "segmentDefsAddr",
    "prizeDefsAddr",
}

local REQUIRED_SIZE_FIELDS = {
    -- Struct sizes (must be > 0)
    "sizeofPokemon",
    "sizeofBattlePokemon",
    "sizeofBattleMove",
    "sizeofBaseStatsPokemon",
    "sizeofItem",
    "sizeofAbility",
    -- Entry counts (must be > 0)
    "gNumSpecies",
    "gNumMoves",
    "abilitiesCount",
    "itemsCount",
    "segmentDefsCount",
    "prizeDefsCount",
}

local REQUIRED_OFFSET_FIELDS = {
    -- RogueMon state offsets
    "segmentStateOffset",
    "prizeStateOffset",
    "prizeHistoryOffset",
    -- Data access offsets
    "offsetSpeciesName",
    "offsetMoveName",
    "offsetAbilityName",
    "offsetItemName",
}

function RoguemonGameSettings.validateRequiredFields()
    local errors = {}

    -- Check pointer fields (must be non-nil and non-zero)
    for _, field in ipairs(REQUIRED_POINTER_FIELDS) do
        local val = rawget(GameSettings, field)
        if val == nil then
            table.insert(errors, string.format("Missing required field: %s", field))
        elseif type(val) ~= "number" then
            table.insert(errors, string.format("Invalid type for %s: expected number, got %s", field, type(val)))
        elseif val == 0 then
            table.insert(errors, string.format("Required pointer %s is zero", field))
        end
    end

    -- Check size/count fields (must be non-nil, number, and > 0)
    for _, field in ipairs(REQUIRED_SIZE_FIELDS) do
        local val = rawget(GameSettings, field)
        if val == nil then
            table.insert(errors, string.format("Missing required field: %s", field))
        elseif type(val) ~= "number" then
            table.insert(errors, string.format("Invalid type for %s: expected number, got %s", field, type(val)))
        elseif val <= 0 then
            table.insert(errors, string.format("Required size/count %s must be > 0, got %d", field, val))
        end
    end

    -- Check offset fields (must be non-nil and number; 0 may be valid)
    for _, field in ipairs(REQUIRED_OFFSET_FIELDS) do
        local val = rawget(GameSettings, field)
        if val == nil then
            table.insert(errors, string.format("Missing required field: %s", field))
        elseif type(val) ~= "number" then
            table.insert(errors, string.format("Invalid type for %s: expected number, got %s", field, type(val)))
        end
    end

    if #errors > 0 then
        local msg = "GameSettings validation failed:\n" .. table.concat(errors, "\n")
        Utils.printDebug("[ERROR] %s", msg)
        return false, msg
    end

    return true
end

return RoguemonGameSettings